    "contracts/h33.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC4626} from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IXHood} from "./interface/IXHood.sol";
import {IH33} from "./interface/IH33.sol";

/// @title Canonical xHood Wrapper for Hood Exchange on Sonic
/// @dev Autocompounding shares token voting optimally each epoch
contract h33 is ERC4626, IH33, ReentrancyGuard {
    using SafeERC20 for ERC20;

    /// @inheritdoc IH33
    address public operator;

    IERC20 public immutable hood;
    IXHood public immutable xHood;

    bool public isLocked;

    modifier whileNotLocked() {
        require(isUnlocked(), LOCKED());
        _;
    }

    modifier onlyOperator() {
        require(msg.sender == operator, NOT_AUTHORIZED(msg.sender));
        _;
    }

    constructor(
        address _operator,
        address _xHood
    ) ERC20("SwapHood Liquid Staking Token", "s33") ERC4626(IERC20(_xHood)) {
        operator = _operator;
        xHood = IXHood(_xHood);
        hood = IERC20(xHood.HOOD());
        /// @dev pre-approve hood and xHood
        hood.approve(address(xHood), type(uint256).max);
    }

    /// @inheritdoc IH33
    function compound() external onlyOperator {
        /// @dev fetch the current ratio prior to compounding
        uint256 currentRatio = ratio();
        /// @dev cache the current hood balance
        uint256 currentHoodBalance;
        /// @dev fetch from simple IERC20 call to the underlying HOOD
        currentHoodBalance = hood.balanceOf(address(this));
        /// @dev convert to xHood
        xHood.convertEmissionsToken(currentHoodBalance);
        /// @dev fetch new ratio
        uint256 newRatio = ratio();

        emit Compounded(currentRatio, newRatio, currentHoodBalance);
    }

    /// @inheritdoc IH33
    function rescue(
        address _token,
        uint256 _amount
    ) external nonReentrant onlyOperator {
        uint256 snapshotxHoodBalance = totalAssets();

        /// @dev transfer to the caller
        IERC20(_token).transfer(msg.sender, _amount);

        /// @dev _token could be any malicious contract someone sent to the h33 module
        /// @dev extra security check to ensure xHood balance or allowance doesn't change when rescued
        require(
            xHood.allowance(_token, address(this)) == 0,
            FORBIDDEN_TOKEN(address(xHood))
        );
        require(
            totalAssets() == snapshotxHoodBalance,
            FORBIDDEN_TOKEN(address(xHood))
        );
    }

    function lock() external onlyOperator {
        isLocked = true;

        emit Locked(block.timestamp);
    }

    /// @inheritdoc IH33
    function unlock() external onlyOperator {
        isLocked = false;

        emit Unlocked(block.timestamp);
    }
    /// @inheritdoc IH33

    function transferOperator(address _newOperator) external onlyOperator {
        address currentOperator = operator;

        /// @dev set the new operator
        operator = _newOperator;

        emit NewOperator(currentOperator, operator);
    }
    
    /**
     * Read Functions
     */

    /// @inheritdoc ERC4626
    function totalAssets() public view override returns (uint256) {
        /// @dev simple call to the xHood balance of this contract
        return xHood.balanceOf(address(this));
    }

    /// @inheritdoc IH33
    function ratio() public view returns (uint256) {
        if (totalSupply() == 0) return 1e18;
        return (totalAssets() * 1e18) / totalSupply();
    }

    /// @inheritdoc IH33
    function isUnlocked() public view returns (bool) {
        return isLocked == false;
    }

    /// @inheritdoc IH33
    function isCooldownActive() public view returns (bool) {
        return isLocked == true;
    }

    /**
     * ERC4626 internal overrides
     */
    function _deposit(
        address caller,
        address receiver,
        uint256 assets,
        uint256 shares
    ) internal virtual override whileNotLocked {
        SafeERC20.safeTransferFrom(xHood, caller, address(this), assets);

        _mint(receiver, shares);

        emit Deposit(caller, receiver, assets, shares);
    }

    function _withdraw(
        address caller,
        address receiver,
        address owner,
        uint256 assets,
        uint256 shares
    ) internal virtual override whileNotLocked {
        if (caller != owner) {
            _spendAllowance(owner, caller, shares);
        }

        _burn(owner, shares);

        SafeERC20.safeTransfer(xHood, receiver, assets);

        emit Withdraw(caller, receiver, owner, assets, shares);
    }
}
"
    },
    "contracts/interface/IH33.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IH33 is IERC20 {
    /**
     * Error strings
     */
    error ZERO();
    error NOT_ENOUGH();
    error NOT_CONFORMED_TO_SCALE(uint256);
    error LOCKED();
    error REBASE_IN_PROGRESS();
    error FORBIDDEN_TOKEN(address);
    error NOT_AUTHORIZED(address);

    event Entered(address indexed user, uint256 amount, uint256 ratioAtDeposit);
    event Exited(address indexed user, uint256 _outAmount, uint256 ratioAtWithdrawal);

    event NewOperator(address _oldOperator, address _newOperator);
    event Compounded(uint256 oldRatio, uint256 newRatio, uint256 amount);

    event Locked(uint256 _ts);
    event Unlocked(uint256 _ts);

    event UpdatedIndex(uint256 _index);

    /// @notice compounds any existing SHADOW within the contract
    function compound() external;

    /// @notice rescue stuck tokens
    function rescue(address _token, uint256 _amount) external;

    /// @notice allows the operator to lock the contract for the current period
    function lock() external;

    /// @notice allows the operator to unlock the contract for the current period
    function unlock() external;

    /// @notice transfers the operator via accesshub
    function transferOperator(address _newOperator) external;

    /// @notice if the contract is unlocked for deposits
    function isUnlocked() external view returns (bool);

    /// @notice determines whether the cooldown is active
    function isCooldownActive() external view returns (bool);

    /// @notice address of the current operator
    function operator() external view returns (address);

    /// @notice returns the ratio of xShadow per H33 token
    function ratio() external view returns (uint256 _ratio);
}
"
    },
    "contracts/interface/IXHood.sol": {
      "content": "// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IXHood is IERC20 {
    error NOT_WHITELISTED(address);
    error NOT_MINTER();
    error ZERO();
    error NO_VEST();
    error ALREADY_EXEMPT();
    error NOT_EXEMPT();
    error CANT_RESCUE();
    error NO_CHANGE();
    error ARRAY_LENGTHS();
    error TOO_HIGH();

    event InstantExit(address indexed user, uint256);

    event NewSlashingPenalty(uint256 penalty);

    event NewVest(
        address indexed user,
        uint256 indexed vestId,
        uint256 indexed amount
    );

    event Converted(address indexed user, uint256);

    event Exemption(address indexed candidate, bool status, bool success);

    event XHoodRedeemed(address indexed user, uint256);

    event NewOperator(address indexed o, address indexed n);

    event Rebase(address indexed caller, uint256 amount);

    /// @notice address of the hood token
    function HOOD() external view returns (IERC20);

    /// @notice address of the operator
    function operator() external view returns (address);

    /// @notice max slashing amount
    function SLASHING_PENALTY() external view returns (uint256);

    /// @notice denominator
    function BASIS() external view returns (uint256);

    function hood() external view returns (address);

    /// @notice amount of pvp rebase penalties accumulated pending to be distributed
    function pendingRebase() external view returns (uint256);

    /// @notice pauses the contract
    function pause() external;

    /// @notice unpauses the contract
    function unpause() external;

    /*****************************************************************/
    // General use functions
    /*****************************************************************/

    /// @dev mints xHoods for each hood.
    function convertEmissionsToken(uint256 _amount) external;

    /// @notice function called by the minter to send the rebases once a week
    function rebase() external;
    /**
     * @dev exit instantly with a penalty
     * @param _amount amount of xHoods to exit
     */
    function exit(uint256 _amount) external returns(uint256 _exitedAmount);

    /*****************************************************************/
    // Permissioned functions, timelock/operator gated
    /*****************************************************************/

    /// @dev allows the operator to redeem collected xHoods
    function operatorRedeem(uint256 _amount) external;

    /// @dev allows rescue of any non-stake token
    function rescueTrappedTokens(
        address[] calldata _tokens,
        uint256[] calldata _amounts
    ) external;

    /// @notice migrates the operator to another contract
    function migrateOperator(address _operator) external;

    /// @notice set exemption status for an address
    function setExemption(
        address[] calldata _exemptee,
        bool[] calldata _exempt
    ) external;

    function setExemptionTo(
        address[] calldata _exemptee,
        bool[] calldata _exempt
    ) external;

    /*****************************************************************/
    // Getter functions
    /*****************************************************************/

    /// @notice returns the amount of HOOD within the contract
    function getBalanceResiding() external view returns (uint256);

    /// @notice whether the address is exempt
    /// @param _who who to check
    /// @return _exempt whether it's exempt
    function isExempt(address _who) external view returns (bool _exempt);
}
"
    },
    "contracts/xHOOD.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

import {IXHood} from "./interface/IXHood.sol";

contract xHOOD is ERC20, IXHood, Pausable {
    using EnumerableSet for EnumerableSet.AddressSet;

    /** Addresses */

    /// @inheritdoc IXHood
    address public operator;

    /// @dev IERC20 declaration of Hood
    IERC20 public immutable HOOD;

    /// @dev stores the addresses that are exempt from transfer limitations when transferring out
    EnumerableSet.AddressSet exempt;
    /// @dev stores the addresses that are exempt from transfer limitations when transferring to them
    EnumerableSet.AddressSet exemptTo;

    /// @inheritdoc IXHood
    uint256 public pendingRebase;

    /// @inheritdoc IXHood
    uint256 public constant BASIS = 10_000;
    /// @inheritdoc IXHood
    uint256 public constant SLASHING_PENALTY = 5000;

    modifier onlyGovernance() {
        require(msg.sender == operator, "NOT_AUTHORIZED");
        _;
    }

    constructor(
        address _hood,
        address _operator
    ) ERC20("xSwt", "xSWT") {
        HOOD = IERC20(_hood);
        operator = _operator;

        exempt.add(operator);
    }

    /// @inheritdoc IXHood
    function pause() external onlyGovernance {
        _pause();
    }
    /// @inheritdoc IXHood
    function unpause() external onlyGovernance {
        _unpause();
    }

    /*****************************************************************/
    // ERC20 Overrides and Helpers
    /*****************************************************************/

    function _update(
        address from,
        address to,
        uint256 value
    ) internal override {
        /* cases we account for:
         *
         * minting and burning
         * if the "to" is part of the special exemptions
         * withdraw and deposit calls
         * if "from" is a gauge or feeDist
         *
         */

        uint8 _u;
        if (_isExempted(from, to)) {
            _u = 1;
        }
        /// @dev if all previous checks are passed
        require(_u == 1, NOT_WHITELISTED(from));
        /// @dev call parent function
        super._update(from, to, value);
    }

    /// @dev internal check for the transfer whitelist
    function _isExempted(
        address _from,
        address _to
    ) internal view returns (bool) {
        return (exempt.contains(_from) ||
            _from == address(0) ||
            _to == address(0) ||
            exemptTo.contains(_to));
    }

    /*****************************************************************/
    // General use functions
    /*****************************************************************/

    /// @inheritdoc IXHood
    function convertEmissionsToken(uint256 _amount) external whenNotPaused {
        /// @dev ensure the _amount is > 0
        require(_amount != 0, ZERO());
        /// @dev transfer from the caller to this address
        HOOD.transferFrom(msg.sender, address(this), _amount);
        /// @dev mint the xHOOD to the caller
        _mint(msg.sender, _amount);
        /// @dev emit an event for conversion
        emit Converted(msg.sender, _amount);
    }

    /// @inheritdoc IXHood
    function rebase() external whenNotPaused onlyGovernance {
        if (
            pendingRebase >= BASIS
        ) {
            /// @dev store the rebase
            uint256 _temp = pendingRebase;
            /// @dev zero it out
            pendingRebase = 0;

            HOOD.transfer(operator, _temp);
            emit Rebase(msg.sender, _temp);
        }
    }

    /// @inheritdoc IXHood
    function exit(
        uint256 _amount
    ) external whenNotPaused returns (uint256 _exitedAmount) {
        /// @dev cannot exit a 0 amount
        require(_amount != 0, ZERO());
        /// @dev if it's at least 2 wei it will give a penalty
        uint256 penalty = ((_amount * SLASHING_PENALTY) / BASIS);
        uint256 exitAmount = _amount - penalty;

        /// @dev burn the xHood from the caller's address
        _burn(msg.sender, _amount);

        /// @dev store the rebase earned from the penalty
        pendingRebase += penalty;

        /// @dev transfer the exitAmount to the caller
        HOOD.transfer(msg.sender, exitAmount);
        /// @dev emit actual exited amount
        emit InstantExit(msg.sender, exitAmount);
        return exitAmount;
    }


    /*****************************************************************/
    // Permissioned functions, timelock/operator gated
    /*****************************************************************/

    /// @inheritdoc IXHood
    function operatorRedeem(uint256 _amount) external onlyGovernance {
        _burn(operator, _amount);
        HOOD.transfer(operator, _amount);
        emit XHoodRedeemed(address(this), _amount);
    }

    /// @inheritdoc IXHood
    function rescueTrappedTokens(
        address[] calldata _tokens,
        uint256[] calldata _amounts
    ) external onlyGovernance {
        for (uint256 i = 0; i < _tokens.length; ++i) {
            /// @dev cant fetch the underlying
            require(_tokens[i] != address(HOOD), CANT_RESCUE());
            IERC20(_tokens[i]).transfer(operator, _amounts[i]);
        }
    }

    /// @inheritdoc IXHood
    function migrateOperator(address _operator) external onlyGovernance {
        /// @dev ensure operator is different
        require(operator != _operator, NO_CHANGE());
        emit NewOperator(operator, _operator);
        operator = _operator;
    }

    /// @inheritdoc IXHood
    function setExemption(
        address[] calldata _exemptee,
        bool[] calldata _exempt
    ) external onlyGovernance {
        /// @dev ensure arrays of same length
        require(_exemptee.length == _exempt.length, ARRAY_LENGTHS());
        /// @dev loop through all and attempt add/remove based on status
        for (uint256 i = 0; i < _exempt.length; ++i) {
            bool success = _exempt[i]
                ? exempt.add(_exemptee[i])
                : exempt.remove(_exemptee[i]);
            /// @dev emit : (who, status, success)
            emit Exemption(_exemptee[i], _exempt[i], success);
        }
    }

    /// @inheritdoc IXHood
    function setExemptionTo(
        address[] calldata _exemptee,
        bool[] calldata _exempt
    ) external onlyGovernance {
        /// @dev ensure arrays of same length
        require(_exemptee.length == _exempt.length, ARRAY_LENGTHS());
        /// @dev loop through all and attempt add/remove based on status
        for (uint256 i = 0; i < _exempt.length; ++i) {
            bool success = _exempt[i]
                ? exemptTo.add(_exemptee[i])
                : exemptTo.remove(_exemptee[i]);
            /// @dev emit : (who, status, success)
            emit Exemption(_exemptee[i], _exempt[i], success);
        }
    }

    /*****************************************************************/
    // Getter functions
    /*****************************************************************/

    /// @inheritdoc IXHood
    function getBalanceResiding() public view returns (uint256 _amount) {
        /// @dev simply returns the balance of the underlying
        return HOOD.balanceOf(address(this));
    }

    /// @inheritdoc IXHood
    function isExempt(address _who) external view returns (bool _exempt) {
        return exempt.contains(_who);
    }

    /// @inheritdoc IXHood
    function hood() external view returns (address) {
        return address(HOOD);
    }
}
"
    }
  },
  "settings": {
    "evmVersion": "cancun",
    "viaIR": true,
    "optimizer": {
      "enabled": true,
      "runs": 200
    },
    "outputSelection": {
      "*": {
        "*": [
          "evm.bytecode",
          "evm.deployedBytecode",
          "devdoc",
          "userdoc",
          "metadata",
          "abi"
        ]
      }
    }
  }
}}
